from __future__ import annotations
from datetime import datetime
from pathlib import Path
import re, shutil, py_compile
ROOT=Path(__file__).resolve().parent
APP=ROOT/"app"; TEMPLATES=APP/"templates"; STATIC=APP/"static"
if not TEMPLATES.exists() or not STATIC.exists(): raise SystemExit("Execute na raiz do projeto, onde existe app/templates e app/static.")
backup=ROOT/f"backup_editor_proposta_{datetime.now():%Y%m%d_%H%M%S}"; backup.mkdir(parents=True)
files=[TEMPLATES/"proposal_new.html",TEMPLATES/"proposal_edit.html",TEMPLATES/"_proposal_access_editor.html",STATIC/"proposal-access-editor.css",STATIC/"proposal-access-editor.js"]
for src in files:
    if src.exists():
        dst=backup/src.relative_to(APP); dst.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(src,dst)
component='<!-- PROPOSAL_ACCESS_EDITOR_START -->\n<link rel="stylesheet" href="{{ url_for(\'static\', path=\'proposal-access-editor.css\') }}">\n<section class="pae-shell" data-proposal-access-editor>\n  <header class="pae-header">\n    <div><h2>Permissões da proposta</h2><p>Selecione uma tela no menu e configure seus botões à direita.</p></div>\n    <div class="pae-stats"><span><b data-selected-screens>0</b> telas</span><span><b data-selected-buttons>0</b> botões</span></div>\n  </header>\n  <div class="pae-toolbar">\n    <input type="search" data-tree-search placeholder="Pesquisar caminho, tela ou botão">\n    <label><input type="checkbox" data-only-selected> Somente selecionados</label>\n    <button type="button" data-expand-all>Expandir</button><button type="button" data-collapse-all>Recolher</button>\n  </div>\n  <div class="pae-columns">\n    <fieldset class="pae-tree-panel"><legend>Opções do Menu</legend><div class="pae-tree" data-tree></div></fieldset>\n    <fieldset class="pae-actions-panel"><legend>Acessos</legend>\n      <div class="pae-empty" data-empty>Selecione uma tela para configurar seus botões.</div>\n      <div class="pae-action-content" data-action-content hidden>\n        <div class="pae-action-head"><div><small data-selected-path></small><h3 data-selected-title></h3></div>\n          <label class="pae-screen-toggle"><input type="checkbox" data-screen-toggle><span>Permitir tela</span></label>\n        </div>\n        <div class="pae-action-tools"><button type="button" data-check-all>Permitir todos</button><button type="button" data-uncheck-all>Negar todos</button></div>\n        <div class="pae-actions" data-actions></div>\n      </div>\n    </fieldset>\n  </div>\n  <input type="hidden" name="proposal_selection_json" data-selection-input>\n  <script type="application/json" data-catalog-json>{{ arvore_permissoes|default([])|tojson }}</script>\n  <script type="application/json" data-selection-json>{{ proposta_permissoes|default({})|tojson }}</script>\n</section>\n<script src="{{ url_for(\'static\', path=\'proposal-access-editor.js\') }}" defer></script>\n<!-- PROPOSAL_ACCESS_EDITOR_END -->'
css=':root{--pae-border:#c7cdd3;--pae-line:#9ea8b1;--pae-select:#d7e8fa;--pae-green:#14863c;--pae-red:#d22626}.pae-shell{margin:16px 0;border:1px solid var(--pae-border);background:#fff;font:13px "Segoe UI",Tahoma,Arial,sans-serif;color:#20262b}.pae-header{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:10px 12px;border-bottom:1px solid var(--pae-border);background:#f6f8fa}.pae-header h2{margin:0 0 3px;font-size:17px}.pae-header p{margin:0;color:#65717b}.pae-stats{display:flex;gap:7px}.pae-stats span{padding:4px 8px;border-radius:12px;background:#eaf0f5}.pae-toolbar{display:flex;align-items:center;gap:8px;padding:8px 10px;border-bottom:1px solid var(--pae-border)}.pae-toolbar input[type=search]{flex:1;min-width:220px;padding:7px;border:1px solid #adb7c0}.pae-toolbar button,.pae-action-tools button{padding:6px 9px;border:1px solid #aeb8c1;background:#fff;border-radius:3px;cursor:pointer}.pae-columns{display:grid;grid-template-columns:minmax(390px,60%) minmax(320px,40%);min-height:560px}.pae-tree-panel,.pae-actions-panel{margin:7px;padding:0;border:1px solid var(--pae-border);min-width:0}.pae-tree-panel{margin-right:0}.pae-actions-panel{margin-left:5px}.pae-tree-panel legend,.pae-actions-panel legend{padding:0 6px;font-weight:600}.pae-tree{height:535px;overflow:auto;padding:7px 9px 16px}.pae-empty{height:510px;display:flex;align-items:center;justify-content:center;color:#68737d}.pae-branch{position:relative}.pae-children{margin-left:20px;padding-left:12px;border-left:1px dotted var(--pae-line)}.pae-node{position:relative;display:flex;align-items:center;gap:5px;min-height:27px;padding:2px 5px;border-radius:2px;white-space:nowrap}.pae-children>.pae-branch>.pae-node:before{content:"";position:absolute;left:-13px;top:13px;width:12px;border-top:1px dotted var(--pae-line)}.pae-node:hover{background:#edf5fc}.pae-node.active{background:var(--pae-select);outline:1px solid #b1cce8}.pae-expander{width:14px;height:14px;padding:0;border:1px solid #7b8790;background:#fff;font-size:11px;line-height:11px}.pae-expander.blank{visibility:hidden}.pae-folder-icon{width:17px;height:12px;border:1px solid #ad791a;border-radius:2px;background:linear-gradient(#f7ce68,#e7a92e);position:relative}.pae-folder-icon:before{content:"";position:absolute;left:1px;top:-5px;width:8px;height:5px;border:1px solid #ad791a;border-bottom:0;background:#efbb48}.pae-screen-icon{font-size:20px;font-weight:700;width:18px;text-align:center}.pae-screen-icon.allowed{color:var(--pae-green)}.pae-screen-icon.denied{color:var(--pae-red)}.pae-node-name{cursor:pointer;overflow:hidden;text-overflow:ellipsis}.pae-node-count{margin-left:auto;color:#71808d;font-size:11px}.pae-children[hidden],.pae-filtered{display:none!important}.pae-action-content{height:510px;display:flex;flex-direction:column}.pae-action-head{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:9px 11px;border-bottom:1px solid #d8dde2;background:#fafbfc}.pae-action-head small{color:#6c7781}.pae-action-head h3{margin:3px 0 0;font-size:15px}.pae-screen-toggle{display:flex;gap:6px;align-items:center;font-weight:600}.pae-action-tools{display:flex;gap:6px;padding:7px 10px;border-bottom:1px solid #e0e4e8}.pae-actions{overflow:auto;flex:1}.pae-action-row{display:grid;grid-template-columns:24px 1fr auto;gap:6px;align-items:center;min-height:34px;padding:4px 9px;border-bottom:1px solid #e7eaed}.pae-action-status{font-size:11px;font-weight:700;padding:2px 7px;border-radius:10px}.pae-action-status.allowed{color:#087c2e;background:#d8f4df}.pae-action-status.denied{color:#bd1d17;background:#fde0dd}.pae-action-row input{width:15px;height:15px;accent-color:var(--pae-green)}@media(max-width:900px){.pae-columns{grid-template-columns:1fr}.pae-tree-panel,.pae-actions-panel{margin:7px}.pae-tree{height:380px}.pae-action-content,.pae-empty{height:410px}.pae-toolbar{flex-wrap:wrap}}'
js='(() => {\n"use strict";\nconst q=(r,s)=>r.querySelector(s), qa=(r,s)=>[...r.querySelectorAll(s)], clone=v=>JSON.parse(JSON.stringify(v));\nconst parse=(el,f)=>{try{return JSON.parse(el?.textContent?.trim()||"")||f}catch{return f}};\nconst esc=v=>String(v??"").replace(/[&<>"\']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",\'"\':"&quot;","\'":"&#039;"}[c]));\nconst sid=v=>String(v).replace(/[^a-zA-Z0-9_-]/g,"_");\nfunction catalog(raw){const out=[];function walk(nodes,parent=[]){(nodes||[]).forEach(n=>{const name=n.nome||n.name||n.label||"Sem nome",children=n.filhos||n.children||[],type=n.tipo||n.type||(children.length?"pasta":"tela"),id=String(n.id??n.chave??[...parent,name].join("|||"));if(type==="pasta"||children.length){walk(children,[...parent,name]);return}const actions=(n.permissoes||n.acoes||n.botoes||n.actions||[]).map((a,i)=>({id:String(a.id??a.chave??`${id}|||${a.nome||a.name||a.botao||i}`),name:a.nome||a.name||a.botao||"Ação",description:a.descricao||a.description||a.caminho||""}));out.push({id,name,path:[...parent,name],actions})})}walk(raw,[]);return out}\nfunction start(root){if(root.dataset.ready)return;root.dataset.ready="1";const screens=catalog(parse(q(root,"[data-catalog-json]"),[])),raw=parse(q(root,"[data-selection-json]"),{}),selection={},byId=Object.fromEntries(screens.map(s=>[s.id,s])),tree=q(root,"[data-tree]"),actions=q(root,"[data-actions]");screens.forEach(s=>{const r=raw[s.id]||{},a={};s.actions.forEach(x=>a[x.id]=Boolean(r.permissoes?.[x.id]??r.actions?.[x.id]??r[x.id]));selection[s.id]={screen:Boolean(r.acesso??r.screen??Object.values(a).some(Boolean)),actions:a}});let active=screens.find(s=>selected(s))?.id||screens[0]?.id||null,search="",only=false;const expanded=new Set(screens.map(s=>s.path[0]));\nfunction count(s){return Object.values(selection[s.id].actions).filter(Boolean).length}function selected(s){return selection[s.id].screen||count(s)>0}function key(a){return a.join("|||+")}function sync(){q(root,"[data-selection-input]").value=JSON.stringify(selection);q(root,"[data-selected-screens]").textContent=screens.filter(selected).length;q(root,"[data-selected-buttons]").textContent=screens.reduce((n,s)=>n+count(s),0)}\nfunction screenRow(s){const on=selected(s),n=count(s),txt=(s.path.join(" ")+" "+s.actions.map(a=>a.name).join(" ")).toLowerCase(),show=(!search||txt.includes(search))&&(!only||on);return `<div class="pae-branch ${show?"":"pae-filtered"}" data-screen="${esc(s.id)}"><div class="pae-node ${s.id===active?"active":""}"><span class="pae-expander blank"></span><span class="pae-screen-icon ${on?"allowed":"denied"}">${on?"✓":"×"}</span><span class="pae-node-name" data-select="${esc(s.id)}">${esc(s.name)}</span><span class="pae-node-count">${n}</span></div></div>`}\nfunction drawTree(){const model={};screens.forEach(s=>{let n=model;s.path.slice(0,-1).forEach(p=>n=n[p]??={_:{}});(n._screens??=[]).push(s)});function render(node,parts=[]){return Object.entries(node).filter(([k])=>!k.startsWith("_")).map(([name,ch])=>{const k=key([...parts,name]),open=expanded.has(k)||expanded.has(name),inside=render(ch,[...parts,name])+(ch._screens||[]).map(screenRow).join("");if(!inside&&!(!search&& !only))return "";return `<div class="pae-branch"><div class="pae-node"><button type="button" class="pae-expander" data-folder="${esc(k)}">${open?"−":"+"}</button><span class="pae-folder-icon"></span><span class="pae-node-name" data-folder="${esc(k)}">${esc(name)}</span></div><div class="pae-children" ${open?"":"hidden"}>${inside}</div></div>`}).join("")}tree.innerHTML=render(model)+(model._screens||[]).map(screenRow).join("")}\nfunction drawActions(){const s=byId[active];if(!s){q(root,"[data-empty]").hidden=false;q(root,"[data-action-content]").hidden=true;return}q(root,"[data-empty]").hidden=true;q(root,"[data-action-content]").hidden=false;q(root,"[data-selected-path]").textContent=s.path.slice(0,-1).join(" > ");q(root,"[data-selected-title]").textContent=s.name;const toggle=q(root,"[data-screen-toggle]");toggle.checked=selected(s);toggle.indeterminate=!selection[s.id].screen&&count(s)>0;actions.innerHTML=s.actions.map(a=>{const on=selection[s.id].actions[a.id];return `<div class="pae-action-row"><input type="checkbox" id="pae-${sid(a.id)}" data-action="${esc(a.id)}" ${on?"checked":""}><label for="pae-${sid(a.id)}"><strong>${esc(a.name)}</strong>${a.description?`<small>${esc(a.description)}</small>`:""}</label><span class="pae-action-status ${on?"allowed":"denied"}">${on?"Permitido":"Negado"}</span></div>`}).join("")}\nfunction refresh(){drawTree();drawActions();sync()}function all(s,on){selection[s.id].screen=on;s.actions.forEach(a=>selection[s.id].actions[a.id]=on);refresh()}\ntree.addEventListener("click",e=>{const f=e.target.closest("[data-folder]");if(f){const k=f.dataset.folder;expanded.has(k)?expanded.delete(k):expanded.add(k);drawTree();return}const s=e.target.closest("[data-select]");if(s){active=s.dataset.select;refresh()}});actions.addEventListener("change",e=>{const i=e.target.closest("[data-action]");if(!i)return;selection[active].actions[i.dataset.action]=i.checked;if(i.checked)selection[active].screen=true;else if(!Object.values(selection[active].actions).some(Boolean))selection[active].screen=false;refresh()});q(root,"[data-screen-toggle]").addEventListener("change",e=>all(byId[active],e.target.checked));q(root,"[data-check-all]").addEventListener("click",()=>all(byId[active],true));q(root,"[data-uncheck-all]").addEventListener("click",()=>all(byId[active],false));q(root,"[data-tree-search]").addEventListener("input",e=>{search=e.target.value.trim().toLowerCase();drawTree()});q(root,"[data-only-selected]").addEventListener("change",e=>{only=e.target.checked;drawTree()});q(root,"[data-expand-all]").addEventListener("click",()=>{screens.forEach(s=>s.path.slice(0,-1).forEach((_,i)=>expanded.add(key(s.path.slice(0,i+1))));drawTree()});q(root,"[data-collapse-all]").addEventListener("click",()=>{expanded.clear();drawTree()});refresh()}\ndocument.addEventListener("DOMContentLoaded",()=>document.querySelectorAll("[data-proposal-access-editor]").forEach(start));\n})();'
(TEMPLATES/"_proposal_access_editor.html").write_text(component,encoding="utf-8")
(STATIC/"proposal-access-editor.css").write_text(css,encoding="utf-8")
(STATIC/"proposal-access-editor.js").write_text(js,encoding="utf-8")
include='\n{% include "_proposal_access_editor.html" %}\n'
for name in ["proposal_new.html","proposal_edit.html"]:
    path=TEMPLATES/name
    if not path.exists(): print(f"AVISO: {name} nao encontrado."); continue
    text=path.read_text(encoding="utf-8")
    text=re.sub(r'<!--\s*PROPOSAL_ACCESS_EDITOR_START\s*-->.*?<!--\s*PROPOSAL_ACCESS_EDITOR_END\s*-->','',text,flags=re.S)
    if '_proposal_access_editor.html' not in text:
        m=re.search(r'<button[^>]+type=["\']submit["\'][^>]*>',text,re.I)
        if m:text=text[:m.start()]+include+text[m.start():]
        elif '{% endblock %}' in text:text=text.replace('{% endblock %}',include+'{% endblock %}',1)
        else:text+=include
    path.write_text(text,encoding="utf-8")
print("Editor ERP integrado na tela de proposta.")
print("Backup:",backup)
print("Reinicie o Uvicorn e use Ctrl+F5.")
